import { useEffect, useMemo, useState } from "react";
import { useServerFn } from "@tanstack/react-start";
import { supabase } from "@/integrations/supabase/client";
import type { BrandVoice, ContentPiece, ContentStatus, DraftResult, Platform } from "@/lib/socialpilot.types";
import { DEMO_BRANDS, DEMO_CONTENT, DEMO_TREND, formatShortDate, PLATFORMS } from "@/lib/socialpilot-data";
import { generateSocialContent } from "@/lib/content-generator.functions";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { toast } from "sonner";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Copy, Download, FileText, Hash, LayoutDashboard, Lightbulb, LogOut, Menu, MessageCircle, MoreHorizontal, PenLine, Plus, Search, Settings, Sparkles, Target, Trash2, TrendingUp, Users, WandSparkles, X } from "lucide-react";
import { useNavigate } from "@tanstack/react-router";

type Section = "Overview" | "AI Generator" | "Content Ideas" | "Calendar" | "Scheduled Posts" | "Analytics" | "Brand Voice" | "Settings";
const SECTIONS: { label: Section; icon: typeof LayoutDashboard }[] = [
  { label: "Overview", icon: LayoutDashboard }, { label: "AI Generator", icon: WandSparkles }, { label: "Content Ideas", icon: Lightbulb }, { label: "Calendar", icon: CalendarDays }, { label: "Scheduled Posts", icon: Clock3 }, { label: "Analytics", icon: BarChart3 }, { label: "Brand Voice", icon: MessageCircle }, { label: "Settings", icon: Settings },
];
const STATUS_LABEL: Record<ContentStatus, string> = { draft: "Draft", scheduled: "Scheduled", published: "Published", failed: "Failed" };
const ideaSets = [
  { title: "A day in the life", tag: "Behind the scenes", copy: "Take your audience behind the scenes of {industry} and show the small details that make your process special." },
  { title: "A quick myth-buster", tag: "Educational", copy: "Challenge one common misconception about {industry} and share the practical truth your audience can use today." },
  { title: "Customer spotlight", tag: "Community", copy: "Celebrate a recent customer win and tell the story of what changed after choosing your {industry}." },
  { title: "Three things we wish we knew", tag: "Expert tips", copy: "Share three useful lessons you learned the hard way in {industry}, with one simple next step for each." },
  { title: "Ask the audience", tag: "Conversation", copy: "Invite your community to help decide what comes next for your {industry} with a friendly, focused question." },
  { title: "The tiny detail", tag: "Product story", copy: "Explain the thoughtful detail in your {industry} that most people overlook—and why it matters." },
];
const chartValues = DEMO_TREND.map((value, index) => ({ week: `W${index + 1}`, engagement: value, reach: value * 1.45 }));
const platformClass: Record<Platform, string> = { Instagram: "platform-instagram", Facebook: "platform-facebook", LinkedIn: "platform-linkedin" };
function initialDraft(topic = "") { return { post_text: "", caption: "", hashtags: "", call_to_action: "" } as DraftResult & { topic: string } ; }

export function SocialPilotApp({ demo = false }: { demo?: boolean }) {
  const navigate = useNavigate();
  const [section, setSection] = useState<Section>("Overview");
  const [contents, setContents] = useState<ContentPiece[]>(demo ? DEMO_CONTENT : []);
  const [brands, setBrands] = useState<BrandVoice[]>(demo ? DEMO_BRANDS : []);
  const [displayName, setDisplayName] = useState(demo ? "Alex" : "there");
  const [ready, setReady] = useState(demo);
  const [collapsed, setCollapsed] = useState(false);
  const [search, setSearch] = useState("");
  const [topic, setTopic] = useState("");
  const [platform, setPlatform] = useState<Platform>("Instagram");
  const [tone, setTone] = useState("Warm");
  const [audience, setAudience] = useState("");
  const [goal, setGoal] = useState("Build awareness");
  const [language, setLanguage] = useState("English");
  const [length, setLength] = useState("Medium");
  const [brandId, setBrandId] = useState("");
  const [result, setResult] = useState<DraftResult & { topic: string }>(initialDraft());
  const [generating, setGenerating] = useState(false);
  const [ideasIndustry, setIdeasIndustry] = useState("coffee shop");
  const [calendarDate, setCalendarDate] = useState(() => new Date(2026, 10, 1));
  const [calendarView, setCalendarView] = useState<"Month" | "Week">("Month");
  const [selectedDay, setSelectedDay] = useState<string | null>(null);
  const [scheduleDate, setScheduleDate] = useState("");
  const [brandForm, setBrandForm] = useState({ name: "", description: "", style: "", tone: "Warm", audience: "", preferred_words: "", avoided_words: "" });
  const generateCall = useServerFn(generateSocialContent);

  useEffect(() => {
    if (demo) { setReady(true); return; }
    let mounted = true;
    async function load() {
      const { data: userResult } = await supabase.auth.getUser();
      if (!mounted) return;
      const user = userResult.user;
      if (!user) { setReady(true); return; }
      const metadataName = typeof user.user_metadata?.['display_name'] === "string" ? user.user_metadata['display_name'] : user.email?.split("@")[0] ?? "there";
      setDisplayName(metadataName);
      const [{ data: profile }, { data: voiceRows }, { data: contentRows }] = await Promise.all([
        supabase.from("profiles").select("display_name").eq("id", user.id).maybeSingle(),
        supabase.from("brand_voices").select("*").order("created_at", { ascending: false }),
        supabase.from("content_items").select("*").order("created_at", { ascending: false }),
      ]);
      if (!mounted) return;
      if (profile?.display_name) setDisplayName(profile.display_name);
      const safeBrands = (voiceRows ?? []) as BrandVoice[];
      setBrands(safeBrands);
      const safeContent = (contentRows ?? []) as ContentPiece[];
      setContents(safeContent);
      const firstBrand = safeBrands.find((voice) => voice.is_default) ?? safeBrands[0];
      if (firstBrand) { setBrandId(firstBrand.id); setTone(firstBrand.tone); setAudience(firstBrand.audience); }
      setReady(true);
    }
    void load();
    return () => { mounted = false; };
  }, [demo]);

  const filteredContents = useMemo(() => contents.filter((item) => `${item.title} ${item.topic} ${item.platform} ${item.status}`.toLowerCase().includes(search.toLowerCase())), [contents, search]);
  const upcoming = contents.filter((item) => item.status === "scheduled").sort((a, b) => (a.scheduled_for ?? "").localeCompare(b.scheduled_for ?? "")).slice(0, 3);
  const currentBrand = brands.find((item) => item.id === brandId);
  const openSection = (next: Section) => { setSection(next); setSelectedDay(null); };
  const saveContent = async (status: ContentStatus, scheduledFor: string | null = null) => {
    const body = { title: result.topic || topic || "Untitled draft", platform, status, topic: result.topic || topic, post_text: result.post_text, caption: result.caption, hashtags: result.hashtags, call_to_action: result.call_to_action, scheduled_for: scheduledFor, brand_voice_id: demo ? null : (brandId || null) };
    if (demo) {
      const item: ContentPiece = { ...body, id: `demo-${Date.now()}`, created_at: new Date().toISOString() };
      setContents((current) => [item, ...current]);
      toast.success(status === "scheduled" ? "Added to your demo calendar" : "Saved to demo drafts");
      return;
    }
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) { toast.error("Sign in to save this draft."); return; }
    const { data, error } = await supabase.from("content_items").insert({ ...body, user_id: userData.user.id }).select("*").single();
    if (error) { toast.error("Your draft could not be saved. Please try again."); return; }
    setContents((current) => [data as ContentPiece, ...current]);
    toast.success(status === "scheduled" ? "Added to your content calendar" : "Draft saved");
    setScheduleDate("");
  };
  const changeStatus = async (item: ContentPiece, status: ContentStatus) => {
    const scheduledFor = status === "scheduled" ? (scheduleDate ? new Date(scheduleDate).toISOString() : item.scheduled_for ?? new Date(Date.now() + 86400000).toISOString()) : item.scheduled_for;
    if (demo) {
      setContents((current) => current.map((post) => post.id === item.id ? { ...post, status, scheduled_for: scheduledFor } : post));
      toast.success("Demo content updated");
      return;
    }
    const { error } = await supabase.from("content_items").update({ status, scheduled_for: scheduledFor, updated_at: new Date().toISOString() }).eq("id", item.id);
    if (error) toast.error("Could not update this post.");
    else setContents((current) => current.map((post) => post.id === item.id ? { ...post, status, scheduled_for: scheduledFor } : post));
  };
  const removeContent = async (item: ContentPiece) => {
    if (demo) { setContents((current) => current.filter((post) => post.id !== item.id)); toast.success("Removed from demo content"); return; }
    const { error } = await supabase.from("content_items").delete().eq("id", item.id);
    if (error) toast.error("Could not remove this post."); else setContents((current) => current.filter((post) => post.id !== item.id));
  };
  const saveBrand = async () => {
    if (!brandForm.name.trim()) { toast.error("Add a name for this brand voice."); return; }
    if (demo) {
      const voice: BrandVoice = { ...brandForm, id: `demo-brand-${Date.now()}`, is_default: brands.length === 0 };
      setBrands((current) => [...current, voice]); setBrandId(voice.id); setBrandForm({ name: "", description: "", style: "", tone: "Warm", audience: "", preferred_words: "", avoided_words: "" }); toast.success("Brand voice saved in this demo"); return;
    }
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) { toast.error("Sign in to save a brand voice."); return; }
    const { data, error } = await supabase.from("brand_voices").insert({ ...brandForm, user_id: userData.user.id, is_default: brands.length === 0 }).select("*").single();
    if (error) { toast.error("Could not save this brand voice."); return; }
    setBrands((current) => [data as BrandVoice, ...current]); setBrandId(data.id); setBrandForm({ name: "", description: "", style: "", tone: "Warm", audience: "", preferred_words: "", avoided_words: "" }); toast.success("Brand voice saved");
  };
  const generate = async () => {
    if (topic.trim().length < 2) { toast.error("Add a topic to get started."); return; }
    if (demo) {
      setResult({ topic, post_text: `A fresh perspective on ${topic.toLowerCase()} starts with one thoughtful step. ${ideasIndustry ? `For ${ideasIndustry}, it is the little details that make all the difference.` : "Make space for the moments that matter."}`, caption: `Thoughtful, useful, and made for ${audience || "our community"}. What is your favorite part?`, hashtags: `#${topic.replace(/[^a-zA-Z0-9]/g, "")} #SocialStory #CommunityFirst`, call_to_action: "Tell us what you think" });
      toast.info("Showing an example draft — demo mode does not call AI."); return;
    }
    setGenerating(true);
    try {
      const generated = await generateCall({ data: { topic, platform, tone, audience, goal, language, length, brand: currentBrand ? `${currentBrand.name}: ${currentBrand.description} ${currentBrand.style} Preferred: ${currentBrand.preferred_words}. Avoid: ${currentBrand.avoided_words}.` : "" } });
      setResult({ ...generated, topic });
      toast.success("Your AI draft is ready");
    } catch (error) {
      console.error("Content generation failed", error);
      toast.error(error instanceof Error ? error.message : "The AI draft could not be generated. Your topic is still here.");
    } finally { setGenerating(false); }
  };
  const copyText = async () => {
    const all = [result.post_text, result.caption, result.hashtags, result.call_to_action].filter(Boolean).join("\n\n");
    if (!all) { toast.error("Generate or enter content to copy."); return; }
    try { await navigator.clipboard.writeText(all); toast.success("Content copied"); } catch { toast.error("Clipboard access is unavailable in this browser."); }
  };
  const handleSignOut = async () => {
    await supabase.auth.signOut();
    await navigate({ to: "/auth" });
  };
  const generateIdeas = () => ideaSets.map((idea) => ({ ...idea, copy: idea.copy.replaceAll("{industry}", ideasIndustry || "your industry") }));

  if (!ready) return <div className="flex min-h-screen items-center justify-center bg-background"><div className="flex items-center gap-3 text-sm text-muted-foreground"><span className="h-2 w-2 animate-pulse rounded-full bg-primary" />Preparing your workspace</div></div>;

  return <div className="min-h-screen bg-background text-foreground">
    <aside className={`fixed inset-y-0 left-0 z-40 hidden flex-col border-r border-border bg-card transition-[width] duration-200 lg:flex ${collapsed ? "w-[84px]" : "w-[256px]"}`}>
      <div className="flex h-[76px] items-center gap-3 border-b border-border px-5"><BrandMark /><span className={`${collapsed ? "sr-only" : "block"} whitespace-nowrap font-display text-base font-semibold`}>socialpilot<span className="text-primary"> A</span></span><button type="button" onClick={() => setCollapsed((value) => !value)} aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"} className="ml-auto rounded-md p-1.5 text-muted-foreground transition hover:bg-muted hover:text-foreground">{collapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}</button></div>
      <div className={`mx-3 mt-5 rounded-lg border border-border bg-background p-2.5 ${collapsed ? "hidden" : "block"}`}><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-md bg-accent text-accent-foreground"><span className="font-display text-xs font-bold">SS</span></span><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{demo ? "Sunday Supply" : "My workspace"}</p><p className="text-[10px] text-muted-foreground">{demo ? "Sample workspace" : "Personal workspace"}</p></div><ChevronDown size={14} className="text-muted-foreground" /></div></div>
      <nav aria-label="Dashboard navigation" className="mt-5 flex-1 space-y-1 px-3">{SECTIONS.map((item) => <button key={item.label} type="button" onClick={() => openSection(item.label)} title={collapsed ? item.label : undefined} className={`flex h-10 w-full items-center gap-3 rounded-md px-3 text-left text-[13px] font-medium transition ${section === item.label ? "bg-secondary text-primary" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`}><item.icon size={17} strokeWidth={1.8} /><span className={collapsed ? "sr-only" : ""}>{item.label}</span>{item.label === "Scheduled Posts" && upcoming.length > 0 && !collapsed ? <span className="ml-auto rounded-full bg-accent px-2 py-0.5 text-[10px] text-accent-foreground">{upcoming.length}</span> : null}</button>)}</nav>
      <div className={`mx-3 mb-3 rounded-lg bg-primary p-4 text-primary-foreground ${collapsed ? "hidden" : "block"}`}><div className="mb-2 flex h-8 w-8 items-center justify-center rounded-md bg-primary-foreground/15"><Sparkles size={16} /></div><p className="font-display text-sm font-semibold">A little more magic?</p><p className="mt-1 text-xs leading-relaxed opacity-80">Make every post sound unmistakably like you.</p><button type="button" onClick={() => openSection("Brand Voice")} className="mt-3 text-xs font-semibold underline underline-offset-4">Set up your brand voice</button></div>
      <div className="flex items-center gap-3 border-t border-border p-4"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-brand-lime text-xs font-bold text-foreground">{displayName.slice(0, 1).toUpperCase()}</span><div className={`min-w-0 flex-1 ${collapsed ? "hidden" : "block"}`}><p className="truncate text-xs font-semibold">{displayName}</p><p className="text-[10px] text-muted-foreground">{demo ? "Demo account" : "Free plan"}</p></div>{!demo && <button type="button" onClick={() => void handleSignOut()} aria-label="Sign out" title="Sign out" className={`${collapsed ? "hidden" : "block"} rounded-md p-1.5 text-muted-foreground hover:bg-muted`}><LogOut size={15} /></button>}</div>
    </aside>
    <div className={`min-h-screen transition-[padding] duration-200 ${collapsed ? "lg:pl-[84px]" : "lg:pl-[256px]"}`}>
      <header className="sticky top-0 z-30 flex h-[68px] items-center gap-3 border-b border-border bg-background/95 px-4 backdrop-blur md:px-7"><Sheet><SheetTrigger asChild><Button variant="outline" size="icon" className="lg:hidden" aria-label="Open dashboard navigation"><Menu size={18} /></Button></SheetTrigger><SheetContent side="left" className="w-[280px] p-0"><SheetTitle className="sr-only">Dashboard navigation</SheetTitle><div className="flex h-[76px] items-center gap-3 border-b border-border px-5"><BrandMark /><span className="font-display text-base font-semibold">socialpilot<span className="text-primary"> A</span></span></div><nav className="space-y-1 p-3">{SECTIONS.map((item) => <button key={item.label} onClick={() => openSection(item.label)} className={`flex h-11 w-full items-center gap-3 rounded-md px-3 text-left text-sm ${section === item.label ? "bg-secondary text-primary" : "text-muted-foreground hover:bg-muted"}`}><item.icon size={18} />{item.label}</button>)}</nav>{!demo && <Button variant="ghost" onClick={() => void handleSignOut()} className="mx-3"><LogOut size={16} />Sign out</Button>}</SheetContent></Sheet><div className="flex min-w-0 items-center gap-2 text-xs text-muted-foreground"><span className="hidden sm:inline">Workspace</span><ChevronRight size={14} className="hidden sm:inline" /><span className="truncate font-medium text-foreground">{section}</span>{demo && <span className="ml-1 rounded-full bg-accent px-2 py-1 text-[10px] font-medium text-accent-foreground">DEMO</span>}</div><div className="ml-auto flex items-center gap-2"><div className="relative hidden w-[190px] sm:block xl:w-[240px]"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><Input aria-label="Search content" placeholder="Search anything..." value={search} onChange={(event) => setSearch(event.target.value)} className="h-9 pl-9 text-xs" /></div><Button variant="outline" size="icon" aria-label="Help"><CircleHelp size={17} /></Button><span className="grid h-8 w-8 place-items-center rounded-full bg-brand-lime text-xs font-semibold">{displayName.slice(0, 1).toUpperCase()}</span></div></header>
      {demo && <div role="status" className="flex items-center justify-center gap-2 border-b border-primary/15 bg-secondary px-4 py-2.5 text-center text-xs text-secondary-foreground"><Sparkles size={14} className="shrink-0" /><span>Exploring with sample data. Changes in demo mode stay in this browser session.</span><button className="hidden font-semibold underline underline-offset-2 sm:inline" onClick={() => void navigate({ to: "/auth" })}>Create an account</button></div>}
      <main className="mx-auto max-w-[1500px] px-4 py-7 page-enter sm:px-6 lg:px-9 lg:py-9">
        {section === "Overview" && <OverviewPage demo={demo} name={displayName} contents={contents} upcoming={upcoming} open={openSection} saveContent={saveContent} />}
        {section === "AI Generator" && <GeneratorPage demo={demo} topic={topic} setTopic={setTopic} platform={platform} setPlatform={setPlatform} tone={tone} setTone={setTone} audience={audience} setAudience={setAudience} goal={goal} setGoal={setGoal} language={language} setLanguage={setLanguage} length={length} setLength={setLength} brands={brands} brandId={brandId} setBrandId={setBrandId} result={result} setResult={setResult} generating={generating} generate={generate} copyText={copyText} saveContent={saveContent} />}
        {section === "Content Ideas" && <IdeasPage industry={ideasIndustry} setIndustry={setIdeasIndustry} ideas={generateIdeas()} choose={(idea) => { setTopic(idea); openSection("AI Generator"); }} />}
        {section === "Calendar" && <CalendarPage contents={contents} date={calendarDate} setDate={setCalendarDate} view={calendarView} setView={setCalendarView} selectedDay={selectedDay} setSelectedDay={setSelectedDay} openGenerator={() => openSection("AI Generator")} />}
        {section === "Scheduled Posts" && <PostsPage contents={filteredContents} demo={demo} search={search} scheduleDate={scheduleDate} setScheduleDate={setScheduleDate} changeStatus={changeStatus} remove={removeContent} edit={(item) => { setResult({ topic: item.topic, post_text: item.post_text, caption: item.caption, hashtags: item.hashtags, call_to_action: item.call_to_action }); setTopic(item.topic); setPlatform(item.platform); openSection("AI Generator"); }} />}
        {section === "Analytics" && <AnalyticsPage />}
        {section === "Brand Voice" && <BrandVoicePage brands={brands} form={brandForm} setForm={setBrandForm} save={saveBrand} select={setBrandId} selected={brandId} />}
        {section === "Settings" && <SettingsPage demo={demo} name={displayName} setName={setDisplayName} />}
      </main>
      <footer className="border-t border-border px-6 py-4 text-center text-[11px] text-muted-foreground">{demo ? "Sample workspace · All analytics shown are illustrative" : "Your content stays yours · Publishing and live analytics require platform connections"}</footer>
    </div>
  </div>;
}

function BrandMark() { return <span aria-hidden="true" className="relative grid h-9 w-9 shrink-0 place-items-center overflow-hidden rounded-lg bg-primary text-primary-foreground"><span className="font-display text-lg font-bold">s</span><span className="absolute bottom-1 right-1 h-1.5 w-1.5 rounded-full bg-brand-lime" /></span>; }
function PageHeading({ eyebrow, title, copy, action }: { eyebrow?: string; title: string; copy?: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div>{eyebrow && <p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.16em] text-primary">{eyebrow}</p>}<h1 className="font-display text-2xl font-semibold tracking-tight sm:text-[30px]">{title}</h1>{copy && <p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted-foreground">{copy}</p>}</div>{action && <div className="flex shrink-0 gap-2">{action}</div>}</div>; }
function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`rounded-lg border border-border bg-card ${className}`}>{children}</section>; }
function PanelTitle({ icon: Icon, title, detail, action }: { icon?: typeof Activity; title: string; detail?: string; action?: React.ReactNode }) { return <div className="flex items-center gap-2.5"><div className="grid h-8 w-8 place-items-center rounded-md bg-secondary text-primary">{Icon && <Icon size={16} />}</div><div className="min-w-0 flex-1"><h2 className="truncate text-sm font-semibold">{title}</h2>{detail && <p className="mt-0.5 text-[11px] text-muted-foreground">{detail}</p>}</div>{action}</div>; }
function Pill({ status }: { status: ContentStatus }) { return <span className={`inline-flex w-fit items-center gap-1 rounded-full px-2 py-1 text-[10px] font-medium ${status === "scheduled" ? "bg-secondary text-primary" : status === "published" ? "bg-accent text-accent-foreground" : status === "failed" ? "bg-destructive/10 text-destructive" : "bg-muted text-muted-foreground"}`}><span className={`h-1.5 w-1.5 rounded-full ${status === "scheduled" ? "bg-primary" : status === "published" ? "bg-brand-lime" : status === "failed" ? "bg-destructive" : "bg-muted-foreground"}`} />{STATUS_LABEL[status]}</span>; }
function PlatformTag({ platform }: { platform: Platform }) { return <span className={`rounded-full px-2 py-1 text-[10px] font-semibold ${platformClass[platform]}`}>{platform}</span>; }
function EmptyState({ icon: Icon, title, copy, action }: { icon: typeof FileText; title: string; copy: string; action?: React.ReactNode }) { return <div className="flex min-h-[215px] flex-col items-center justify-center px-5 py-9 text-center"><span className="mb-4 grid h-12 w-12 place-items-center rounded-xl bg-muted text-muted-foreground"><Icon size={21} /></span><h3 className="text-sm font-semibold">{title}</h3><p className="mt-1 max-w-[280px] text-xs leading-relaxed text-muted-foreground">{copy}</p>{action && <div className="mt-4">{action}</div>}</div>; }

function OverviewPage({ demo, name, contents, upcoming, open, saveContent }: { demo: boolean; name: string; contents: ContentPiece[]; upcoming: ContentPiece[]; open: (section: Section) => void; saveContent: (status: ContentStatus, date?: string | null) => Promise<void> }) {
  const recent = contents.slice(0, 3);
  return <><PageHeading eyebrow="Thursday, November 12, 2026" title={`Good morning, ${name}.`} copy="A clear view of what’s moving, and what could use a little spark." action={<><Button variant="outline" onClick={() => open("Content Ideas")}><Lightbulb size={16} />Get ideas</Button><Button onClick={() => open("AI Generator")}><Plus size={16} />New post</Button></>} />
    <div className="mb-7 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[{ label: "Posts this month", value: demo ? "18" : String(contents.length), change: "+4 this week", icon: FileText, paint: "bg-secondary text-primary" }, { label: "Scheduled", value: demo ? "06" : String(contents.filter((post) => post.status === "scheduled").length).padStart(2, "0"), change: "Next up this week", icon: CalendarDays, paint: "bg-accent text-accent-foreground" }, { label: "Engagement rate", value: "4.8%", change: "+0.8% this month", icon: Activity, paint: "bg-primary/10 text-primary" }, { label: "Audience reached", value: "12.4k", change: "+12% this month", icon: Users, paint: "bg-muted text-foreground" }].map((metric) => <Panel key={metric.label} className="p-4"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-muted-foreground">{metric.label}</p><p className="mt-2 font-display text-[26px] font-semibold">{metric.value}</p><p className="mt-1 flex items-center gap-1 text-[11px] text-muted-foreground"><ArrowUpRight size={13} className="text-brand-blue" />{metric.change}</p></div><span className={`grid h-9 w-9 place-items-center rounded-lg ${metric.paint}`}><metric.icon size={17} /></span></div></Panel>)}</div>
    <div className="grid gap-5 xl:grid-cols-[1.55fr_1fr]"><Panel className="p-5"><div className="flex flex-wrap items-center justify-between gap-3"><PanelTitle icon={TrendingUp} title="Content performance" detail="A snapshot of your community activity" /><span className="rounded-full bg-muted px-2.5 py-1 text-[10px] font-medium text-muted-foreground">{demo ? "DEMO DATA" : "SAMPLE DATA"}</span></div><div className="mt-5 grid grid-cols-2 gap-5"><div><p className="text-[11px] text-muted-foreground">Engagement rate</p><p className="mt-1 font-display text-2xl font-semibold">4.8% <span className="font-sans text-xs font-medium text-primary">↑ 0.8%</span></p></div><div><p className="text-[11px] text-muted-foreground">Total interactions</p><p className="mt-1 font-display text-2xl font-semibold">2,846 <span className="font-sans text-xs font-medium text-primary">↑ 12%</span></p></div></div><div className="mt-5 h-[205px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartValues} margin={{ left: -22, right: 5, top: 6, bottom: 0 }}><defs><linearGradient id="engagement-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-primary)" stopOpacity={0.18} /><stop offset="95%" stopColor="var(--color-primary)" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="var(--color-border)" strokeDasharray="4 5" vertical={false} /><XAxis dataKey="week" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: "var(--color-muted-foreground)" }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: "var(--color-muted-foreground)" }} /><Tooltip contentStyle={{ borderRadius: 8, border: "1px solid var(--color-border)", background: "var(--color-card)", color: "var(--color-foreground)", fontSize: 12 }} /><Area type="monotone" dataKey="engagement" stroke="var(--color-primary)" strokeWidth={2.5} fill="url(#engagement-fill)" /></AreaChart></ResponsiveContainer></div></Panel>
      <Panel className="p-5"><div className="flex items-center justify-between"><PanelTitle icon={Clock3} title="Coming up" detail="Your next planned posts" /><button onClick={() => open("Scheduled Posts")} className="text-xs font-semibold text-primary">View all</button></div>{upcoming.length ? <div className="mt-5 space-y-4">{upcoming.map((post) => <div key={post.id} className="flex gap-3 border-b border-border pb-4 last:border-0 last:pb-0"><div className="flex h-12 w-12 shrink-0 flex-col items-center justify-center rounded-md bg-secondary text-primary"><span className="text-[9px] font-semibold uppercase">{post.scheduled_for ? new Date(post.scheduled_for).toLocaleString("en", { month: "short" }) : "Soon"}</span><span className="font-display text-base font-semibold">{post.scheduled_for ? new Date(post.scheduled_for).getDate() : "—"}</span></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-xs font-semibold">{post.title}</p><PlatformTag platform={post.platform} /></div><p className="mt-1 line-clamp-2 text-[11px] leading-relaxed text-muted-foreground">{post.caption || post.post_text}</p><p className="mt-1 text-[10px] text-muted-foreground">{formatShortDate(post.scheduled_for)}</p></div></div>)}</div> : <EmptyState icon={CalendarDays} title="Nothing on the calendar yet" copy="Your scheduled posts will show up here." action={<Button variant="outline" size="sm" onClick={() => open("AI Generator")}>Create a post</Button>} />}</Panel>
      <Panel className="p-5"><div className="flex items-center justify-between"><PanelTitle icon={FileText} title="Recent content" detail="Your latest ideas and drafts" /><button onClick={() => open("Scheduled Posts")} className="text-xs font-semibold text-primary">See all</button></div>{recent.length ? <div className="mt-4 divide-y divide-border">{recent.map((post) => <div key={post.id} className="flex items-center gap-3 py-3 first:pt-0 last:pb-0"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-md bg-muted text-muted-foreground"><PenLine size={15} /></span><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{post.title}</p><p className="mt-1 truncate text-[10px] text-muted-foreground">{post.platform} · {new Date(post.created_at).toLocaleDateString("en", { month: "short", day: "numeric" })}</p></div><Pill status={post.status} /></div>)}</div> : <EmptyState icon={FileText} title="Your first idea starts here" copy="Draft your next post and keep everything organized in one place." action={<Button variant="outline" size="sm" onClick={() => open("AI Generator")}>Start a draft</Button>} />}</Panel>
      <Panel className="p-5"><PanelTitle icon={Activity} title="A few quick moves" detail="Keep your content momentum going" /><div className="mt-4 space-y-2">{[{ label: "Draft an Instagram post", target: "AI Generator" as Section, icon: PenLine }, { label: "Find a fresh content angle", target: "Content Ideas" as Section, icon: Lightbulb }, { label: "Set up your brand voice", target: "Brand Voice" as Section, icon: MessageCircle }].map((action) => <button onClick={() => open(action.target)} key={action.label} className="flex h-11 w-full items-center gap-3 rounded-md border border-border px-3 text-left text-xs font-medium transition hover:bg-muted"><action.icon size={15} className="text-primary" />{action.label}<ArrowRight size={14} className="ml-auto text-muted-foreground" /></button>)}</div><div className="mt-4 flex gap-2 rounded-md bg-muted p-3 text-[10px] leading-relaxed text-muted-foreground"><CircleHelp size={14} className="mt-0.5 shrink-0" />{demo ? "Analytics are illustrative sample data, not connected to a social account." : "External publishing and live analytics activate after official platform connections."}</div></Panel>
    </div>
  </>;
}

function GeneratorPage(props: { demo: boolean; topic: string; setTopic: (v: string) => void; platform: Platform; setPlatform: (v: Platform) => void; tone: string; setTone: (v: string) => void; audience: string; setAudience: (v: string) => void; goal: string; setGoal: (v: string) => void; language: string; setLanguage: (v: string) => void; length: string; setLength: (v: string) => void; brands: BrandVoice[]; brandId: string; setBrandId: (v: string) => void; result: DraftResult & { topic: string }; setResult: (v: DraftResult & { topic: string }) => void; generating: boolean; generate: () => Promise<void>; copyText: () => Promise<void>; saveContent: (status: ContentStatus, date?: string | null) => Promise<void> }) {
  const { demo, topic, setTopic, platform, setPlatform, tone, setTone, audience, setAudience, goal, setGoal, language, setLanguage, length, setLength, brands, brandId, setBrandId, result, setResult, generating, generate, copyText, saveContent } = props;
  return <><PageHeading eyebrow="Your creative co-pilot" title="Make your next post a good one." copy="A thoughtful brief in. A polished, platform-ready starting point out." action={<span className="flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2 text-xs"><Sparkles size={15} className="text-primary" />{demo ? "Sample preview" : "AI writing"}</span>} />
    {demo && <div className="mb-5 flex items-start gap-2 rounded-md border border-primary/15 bg-secondary p-3 text-xs leading-relaxed text-secondary-foreground"><Sparkles size={15} className="mt-0.5 shrink-0" />Demo mode displays a clearly labeled example draft. Sign in to generate original content with AI.</div>}
    <div className="grid items-start gap-5 xl:grid-cols-[0.9fr_1.1fr]"><Panel className="p-5 sm:p-6"><PanelTitle icon={Target} title="Your brief" detail="A little context goes a long way" /><div className="mt-5 space-y-4"><Field label="What are we talking about?" htmlFor="topic"><Textarea id="topic" placeholder="e.g. Our new weekend brunch menu" rows={3} value={topic} onChange={(event) => setTopic(event.target.value)} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Platform" htmlFor="platform"><Select value={platform} onValueChange={(value) => setPlatform(value as Platform)}><SelectTrigger id="platform"><SelectValue /></SelectTrigger><SelectContent>{PLATFORMS.map((name) => <SelectItem key={name} value={name}>{name}</SelectItem>)}</SelectContent></Select></Field><Field label="Tone" htmlFor="tone"><Select value={tone} onValueChange={setTone}><SelectTrigger id="tone"><SelectValue /></SelectTrigger><SelectContent>{["Warm", "Playful", "Professional", "Bold", "Informative", "Minimal"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field></div><Field label="Who are you talking to?" htmlFor="audience"><Input id="audience" placeholder="e.g. Local coffee lovers" value={audience} onChange={(event) => setAudience(event.target.value)} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Your goal" htmlFor="goal"><Select value={goal} onValueChange={setGoal}><SelectTrigger id="goal"><SelectValue /></SelectTrigger><SelectContent>{["Build awareness", "Start a conversation", "Drive visits", "Share expertise", "Promote an offer"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Post length" htmlFor="length"><Select value={length} onValueChange={setLength}><SelectTrigger id="length"><SelectValue /></SelectTrigger><SelectContent>{["Short", "Medium", "Long"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field></div><Field label="Language" htmlFor="language"><Select value={language} onValueChange={setLanguage}><SelectTrigger id="language"><SelectValue /></SelectTrigger><SelectContent>{["English", "Spanish", "French", "German", "Arabic", "Urdu"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Field label="Brand voice" htmlFor="brandvoice"><Select value={brandId || "none"} onValueChange={(value) => { setBrandId(value === "none" ? "" : value); const brand = brands.find((item) => item.id === value); if (brand) { setTone(brand.tone); setAudience(brand.audience); } }}><SelectTrigger id="brandvoice"><SelectValue placeholder="Choose a brand voice" /></SelectTrigger><SelectContent><SelectItem value="none">No brand voice</SelectItem>{brands.map((voice) => <SelectItem key={voice.id} value={voice.id}>{voice.name}</SelectItem>)}</SelectContent></Select></Field><Button className="h-11 w-full" disabled={generating} onClick={() => void generate()}>{generating ? <><span className="h-4 w-4 animate-spin rounded-full border-2 border-primary-foreground/35 border-t-primary-foreground" />Creating your draft…</> : <><Sparkles size={16} />{demo ? "Preview example" : "Generate content"}</>}</Button><p className="text-center text-[10px] leading-relaxed text-muted-foreground">{demo ? "Example copy is not generated by AI." : "Your content is created privately for your workspace."}</p></div></Panel>
      <Panel className="min-w-0 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4"><PanelTitle icon={FileText} title="Your draft" detail={result.topic || "Your new post will appear here"} /><div className="flex gap-1"><Button variant="outline" size="icon" aria-label="Copy all content" title="Copy all content" onClick={() => void copyText()}><Copy size={15} /></Button><Button variant="outline" size="icon" aria-label="Regenerate content" title="Regenerate content" disabled={generating || !topic.trim()} onClick={() => void generate()}><WandSparkles size={15} /></Button></div></div><div className="space-y-4 p-5"><EditableBlock label="POST" value={result.post_text} onChange={(value) => setResult({ ...result, post_text: value })} placeholder="Your main post copy" rows={5} /><EditableBlock label="CAPTION" value={result.caption} onChange={(value) => setResult({ ...result, caption: value })} placeholder="A caption to accompany your post" rows={3} /><EditableBlock label="SUGGESTED HASHTAGS" value={result.hashtags} onChange={(value) => setResult({ ...result, hashtags: value })} placeholder="#Add #your #hashtags" rows={2} /><EditableBlock label="CALL TO ACTION" value={result.call_to_action} onChange={(value) => setResult({ ...result, call_to_action: value })} placeholder="Invite your audience to take the next step" rows={2} /><div className="flex flex-col gap-2 border-t border-border pt-4 sm:flex-row"><Button variant="outline" onClick={() => void saveContent("draft")} className="flex-1"><FileText size={15} />Save draft</Button><Button onClick={() => { if (!result.post_text) toast.info("Create a post first."); else void saveContent("scheduled", new Date(Date.now() + 86400000).toISOString()); }} className="flex-1"><CalendarDays size={15} />Add to calendar</Button></div><div className="rounded-md bg-muted p-3 text-[10px] leading-relaxed text-muted-foreground">Planning only. Automatic publishing to social platforms requires official API access and account connections.</div></div></Panel>
    </div></>;
}
function Field({ label, htmlFor, children }: { label: string; htmlFor: string; children: React.ReactNode }) { return <div className="space-y-1.5"><Label htmlFor={htmlFor} className="text-xs">{label}</Label>{children}</div>; }
function EditableBlock({ label, value, onChange, placeholder, rows }: { label: string; value: string; onChange: (v: string) => void; placeholder: string; rows: number }) { return <div className="space-y-2"><Label className="text-[10px] font-semibold tracking-[0.1em] text-muted-foreground">{label}</Label><Textarea value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} rows={rows} className="resize-y text-sm leading-relaxed" /></div>; }

function IdeasPage({ industry, setIndustry, ideas, choose }: { industry: string; setIndustry: (v: string) => void; ideas: typeof ideaSets; choose: (topic: string) => void }) {
  const [platform, setPlatform] = useState("Any platform");
  return <><PageHeading eyebrow="Find your next angle" title="Good ideas, on demand." copy="Fresh content prompts to keep your feed useful, human, and unmistakably yours." action={<Button onClick={() => toast.success("Your idea list is refreshed") }><Sparkles size={15} />Refresh ideas</Button>} /><Panel className="mb-6 grid gap-3 p-4 sm:grid-cols-[1fr_190px_190px] sm:items-end"><Field label="Industry or niche" htmlFor="niche"><Input id="niche" value={industry} onChange={(event) => setIndustry(event.target.value)} placeholder="e.g. Independent coffee" /></Field><Field label="Platform" htmlFor="idea-platform"><Select value={platform} onValueChange={setPlatform}><SelectTrigger id="idea-platform"><SelectValue /></SelectTrigger><SelectContent>{["Any platform", ...PLATFORMS].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></Field><Button variant="outline" onClick={() => toast.success(`Showing ideas for ${industry || "your niche"}`)}><Target size={15} />Update prompts</Button></Panel><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{ideas.map((idea, index) => <Panel key={idea.title} className="flex min-h-[228px] flex-col p-5 transition hover:border-primary/40"><div className="flex items-center justify-between"><span className="rounded-full bg-secondary px-2.5 py-1 text-[10px] font-medium text-secondary-foreground">{idea.tag}</span><span className="font-display text-xs text-muted-foreground">0{index + 1}</span></div><h2 className="mt-5 font-display text-lg font-semibold">{idea.title}</h2><p className="mt-2 flex-1 text-sm leading-relaxed text-muted-foreground">{idea.copy}</p><Button variant="outline" size="sm" className="mt-5 w-fit" onClick={() => choose(idea.copy)}><WandSparkles size={14} />Make a post</Button></Panel>)}</div></>;
}

function CalendarPage({ contents, date, setDate, view, setView, selectedDay, setSelectedDay, openGenerator }: { contents: ContentPiece[]; date: Date; setDate: (v: Date) => void; view: "Month" | "Week"; setView: (v: "Month" | "Week") => void; selectedDay: string | null; setSelectedDay: (v: string | null) => void; openGenerator: () => void }) {
  const year = date.getFullYear(); const month = date.getMonth();
  const days = new Date(year, month + 1, 0).getDate();
  const offset = new Date(year, month, 1).getDay();
  const selectedPosts = selectedDay ? contents.filter((item) => item.scheduled_for?.slice(0, 10) === selectedDay) : [];
  const calendarCells = view === "Month" ? Array.from({ length: Math.ceil((offset + days) / 7) * 7 }, (_, i) => { const day = i - offset + 1; return day >= 1 && day <= days ? day : null; }) : Array.from({ length: 7 }, (_, i) => (date.getDate() - date.getDay()) + i);
  const move = (amount: number) => { const next = new Date(date); view === "Month" ? next.setMonth(next.getMonth() + amount) : next.setDate(next.getDate() + amount * 7); setDate(next); setSelectedDay(null); };
  return <><PageHeading eyebrow="Plan with intention" title="Your content calendar." copy="A calm view of what’s coming up, and where each idea is headed." action={<Button onClick={openGenerator}><Plus size={15} />New content</Button>} /><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><Button variant="outline" size="icon" aria-label="Previous month" onClick={() => move(-1)}><ChevronLeft size={17} /></Button><h2 className="min-w-[155px] text-center font-display text-base font-semibold">{date.toLocaleDateString("en", { month: "long", year: "numeric" })}</h2><Button variant="outline" size="icon" aria-label="Next month" onClick={() => move(1)}><ChevronRight size={17} /></Button><Button variant="ghost" size="sm" onClick={() => setDate(new Date(2026, 10, 12))}>Today</Button></div><div className="flex rounded-md border border-border p-1">{(["Month", "Week"] as const).map((item) => <button key={item} onClick={() => setView(item)} className={`rounded px-3 py-1.5 text-xs font-medium ${view === item ? "bg-secondary text-primary" : "text-muted-foreground"}`}>{item}</button>)}</div></div><div className="grid gap-4 xl:grid-cols-[1fr_280px]"><Panel className="overflow-hidden"><div className="grid grid-cols-7 border-b border-border bg-muted/60">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => <div key={day} className="py-2.5 text-center text-[10px] font-semibold uppercase text-muted-foreground">{day}</div>)}</div><div className="grid grid-cols-7">{calendarCells.map((day, index) => { const key = day ? `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}` : `blank-${index}`; const posts = day ? contents.filter((item) => item.scheduled_for?.slice(0, 10) === key) : []; return <button key={key} disabled={!day} onClick={() => day && setSelectedDay(key)} className={`flex min-h-[84px] flex-col items-start border-b border-r border-border p-1.5 text-left transition sm:min-h-[112px] sm:p-2 ${day ? "hover:bg-muted/70" : "cursor-default bg-muted/20"} ${selectedDay === key ? "bg-secondary" : ""}`}><span className={`grid h-6 w-6 place-items-center rounded-full text-[11px] ${day === 12 && month === 10 && year === 2026 ? "bg-primary font-semibold text-primary-foreground" : "text-muted-foreground"}`}>{day}</span><span className="mt-1 w-full space-y-1">{posts.slice(0, 2).map((post) => <span key={post.id} className={`block truncate rounded px-1 py-1 text-[9px] ${post.status === "scheduled" ? "bg-secondary text-primary" : "bg-muted text-muted-foreground"}`}>{post.platform === "Instagram" ? "IG · " : post.platform === "Facebook" ? "FB · " : "IN · "}{post.title}</span>)}{posts.length > 2 && <span className="text-[9px] text-muted-foreground">+{posts.length - 2} more</span>}</span></button>; })}</div><div className="flex flex-wrap items-center gap-4 px-4 py-3 text-[10px] text-muted-foreground"><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-primary" />Scheduled</span><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-muted-foreground" />Draft</span></div></Panel><Panel className="p-4"><PanelTitle icon={selectedDay ? CalendarDays : Clock3} title={selectedDay ? new Date(`${selectedDay}T12:00:00`).toLocaleDateString("en", { weekday: "long", month: "short", day: "numeric" }) : "Next up"} detail={selectedDay ? "Planned for this day" : "Your upcoming content"} />{selectedDay ? selectedPosts.length ? <div className="mt-4 space-y-3">{selectedPosts.map((item) => <div key={item.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between gap-2"><PlatformTag platform={item.platform} /><Pill status={item.status} /></div><p className="mt-2 text-xs font-semibold">{item.title}</p><p className="mt-1 line-clamp-3 text-[11px] leading-relaxed text-muted-foreground">{item.caption}</p></div>)}</div> : <EmptyState icon={CalendarDays} title="A clear day" copy="Nothing planned here just yet." action={<Button size="sm" variant="outline" onClick={openGenerator}>Create content</Button>} /> : <div className="mt-4 space-y-4">{contents.filter((item) => item.scheduled_for).slice(0, 4).map((item) => <div key={item.id} className="border-b border-border pb-3 last:border-0"><div className="flex items-center justify-between gap-2"><PlatformTag platform={item.platform} /><span className="text-[10px] text-muted-foreground">{formatShortDate(item.scheduled_for)}</span></div><p className="mt-2 text-xs font-medium">{item.title}</p></div>)}<div className="rounded-md bg-muted p-3 text-[10px] leading-relaxed text-muted-foreground">Calendar dates are for internal planning. Real publishing requires platform API access.</div></div>}</Panel></div></>;
}

function PostsPage({ contents, demo, search, scheduleDate, setScheduleDate, changeStatus, remove, edit }: { contents: ContentPiece[]; demo: boolean; search: string; scheduleDate: string; setScheduleDate: (v: string) => void; changeStatus: (item: ContentPiece, status: ContentStatus) => Promise<void>; remove: (item: ContentPiece) => Promise<void>; edit: (item: ContentPiece) => void }) {
  const [filter, setFilter] = useState<"All" | ContentStatus>("All");
  const filtered = contents.filter((item) => filter === "All" || item.status === filter);
  return <><PageHeading eyebrow="Every post, in its place" title="Your content library." copy="Review drafts, double-check the plan, and keep the next post moving." action={<Button variant="outline" onClick={() => { const csv = ["Title,Platform,Status,Date", ...contents.map((item) => `"${item.title.replaceAll('"', '""')}",${item.platform},${item.status},${item.scheduled_for ?? ""}`)].join("\n"); const blob = new Blob([csv], { type: "text/csv" }); const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = "socialpilot-content.csv"; link.click(); URL.revokeObjectURL(link.href); toast.success("Content list downloaded"); }}><Download size={15} />Export list</Button>} /><div className="mb-4 flex flex-wrap items-center gap-2">{(["All", "draft", "scheduled", "published", "failed"] as const).map((item) => <button key={item} onClick={() => setFilter(item)} className={`rounded-md px-3 py-2 text-xs font-medium ${filter === item ? "bg-primary text-primary-foreground" : "bg-card text-muted-foreground hover:bg-muted"}`}>{item === "All" ? "All posts" : STATUS_LABEL[item]}</button>)}{search && <span className="text-xs text-muted-foreground">Showing results for “{search}”</span>}</div>{filtered.length ? <div className="grid gap-3">{filtered.map((item) => <Panel key={item.id} className="p-4 sm:p-5"><div className="flex flex-col gap-4 md:flex-row md:items-start"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-md bg-secondary text-primary">{item.platform === "Instagram" ? <Sparkles size={18} /> : item.platform === "Facebook" ? <Users size={18} /> : <BarChart3 size={18} />}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="text-sm font-semibold">{item.title}</h2><Pill status={item.status} /><PlatformTag platform={item.platform} /></div><p className="mt-2 line-clamp-2 text-xs leading-relaxed text-muted-foreground">{item.caption || item.post_text}</p><p className="mt-2 text-[10px] text-muted-foreground">{item.scheduled_for ? formatShortDate(item.scheduled_for) : "No date set"} · {new Date(item.created_at).toLocaleDateString("en", { month: "short", day: "numeric" })}</p></div><div className="flex flex-wrap items-center gap-2 md:justify-end"><Input aria-label="Pick a schedule date" type="datetime-local" value={scheduleDate} onChange={(event) => setScheduleDate(event.target.value)} className="h-9 w-[190px] text-xs" /><Button variant="outline" size="sm" onClick={() => void changeStatus(item, item.status === "scheduled" ? "draft" : "scheduled")}>{item.status === "scheduled" ? "Unschedule" : "Schedule"}</Button><Button variant="outline" size="icon" aria-label={`Edit ${item.title}`} onClick={() => edit(item)}><PenLine size={15} /></Button><Button variant="outline" size="icon" aria-label={`Delete ${item.title}`} onClick={() => void remove(item)}><Trash2 size={15} /></Button></div></div></Panel>)}</div> : <Panel><EmptyState icon={Search} title={search ? "No posts found" : "A fresh page"} copy={search ? "Try another title, topic, or platform." : "Saved drafts and scheduled posts will live here."} /></Panel>}<div className="mt-5 flex items-start gap-2 rounded-md border border-border bg-card p-3 text-[11px] leading-relaxed text-muted-foreground"><CircleHelp size={15} className="mt-0.5 shrink-0" />{demo ? "Sample posts and their analytics are illustrative only." : "Scheduling here is an internal planning tool; actual publishing needs official Instagram, Facebook, or LinkedIn access."}</div></>;
}

function AnalyticsPage() {
  const [range, setRange] = useState("Last 30 days");
  return <><PageHeading eyebrow="Learn what resonates" title="A clearer read on your reach." copy="Sample performance gives you a feel for the overview; real account data arrives with official platform connections." action={<Select value={range} onValueChange={setRange}><SelectTrigger className="w-[150px]"><SelectValue /></SelectTrigger><SelectContent>{["Last 7 days", "Last 30 days", "Last 90 days"].map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select>} /><div className="mb-5 rounded-md border border-brand-coral/30 bg-brand-coral/10 px-4 py-3 text-xs leading-relaxed"><span className="font-semibold">Sample analytics only.</span> These figures are illustrative—not live social account data.</div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[{ label: "Audience reached", value: "12.4k", change: "+12.4%", icon: Users }, { label: "Engagement", value: "4.8%", change: "+0.8%", icon: Activity }, { label: "Likes", value: "2,184", change: "+9.2%", icon: Check }, { label: "Comments & shares", value: "662", change: "+6.8%", icon: MessageCircle }].map((item) => <Panel key={item.label} className="p-4"><div className="flex items-center justify-between"><span className="text-xs text-muted-foreground">{item.label}</span><item.icon size={16} className="text-primary" /></div><p className="mt-3 font-display text-[25px] font-semibold">{item.value}</p><p className="mt-1 flex items-center gap-1 text-[11px] text-primary"><ArrowUpRight size={13} />{item.change} vs prior period</p></Panel>)}</div><div className="mt-5 grid gap-5 xl:grid-cols-[1.5fr_1fr]"><Panel className="p-5"><div className="flex items-center justify-between"><PanelTitle icon={TrendingUp} title="Audience & engagement" detail={range} /><span className="rounded-full bg-muted px-2 py-1 text-[10px] text-muted-foreground">DEMO DATA</span></div><div className="mt-5 h-[280px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartValues}><defs><linearGradient id="reach-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-brand-violet)" stopOpacity={0.18} /><stop offset="100%" stopColor="var(--color-brand-violet)" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="var(--color-border)" strokeDasharray="4 5" vertical={false} /><XAxis dataKey="week" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: "var(--color-muted-foreground)" }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: "var(--color-muted-foreground)" }} /><Tooltip contentStyle={{ borderRadius: 8, border: "1px solid var(--color-border)", background: "var(--color-card)", color: "var(--color-foreground)", fontSize: 12 }} /><Area type="monotone" dataKey="reach" stroke="var(--color-brand-violet)" strokeWidth={2} fill="url(#reach-fill)" /><Area type="monotone" dataKey="engagement" stroke="var(--color-primary)" strokeWidth={2} fill="transparent" /></AreaChart></ResponsiveContainer></div><div className="mt-2 flex gap-4 text-[10px] text-muted-foreground"><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-primary" />Engagement</span><span className="flex items-center gap-1.5"><span className="h-2 w-2 rounded-full bg-brand-violet" />Reach</span></div></Panel><Panel className="p-5"><PanelTitle icon={BarChart3} title="Platform comparison" detail="Illustrative activity by channel" /><div className="mt-5 space-y-5">{[{ name: "Instagram", value: 74, number: "1,840" }, { name: "Facebook", value: 48, number: "1,120" }, { name: "LinkedIn", value: 35, number: "864" }].map((item) => <div key={item.name}><div className="mb-2 flex items-center justify-between text-xs"><span className="font-medium">{item.name}</span><span className="text-muted-foreground">{item.number} interactions</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${item.name === "Instagram" ? "bg-primary" : item.name === "Facebook" ? "bg-brand-violet" : "bg-brand-lime"}`} style={{ width: `${item.value}%` }} /></div></div>)}</div><div className="mt-7 rounded-md bg-muted p-3 text-[10px] leading-relaxed text-muted-foreground">Connect a social account to replace sample metrics with your own data.</div></Panel></div></>;
}

function BrandVoicePage({ brands, form, setForm, save, select, selected }: { brands: BrandVoice[]; form: { name: string; description: string; style: string; tone: string; audience: string; preferred_words: string; avoided_words: string }; setForm: (v: typeof form) => void; save: () => Promise<void>; select: (id: string) => void; selected: string }) {
  const change = (key: keyof typeof form, value: string) => setForm({ ...form, [key]: value });
  return <><PageHeading eyebrow="Sound like yourself" title="Make your voice recognizable." copy="Set the guardrails once; keep every draft feeling like it came from you." action={<Button onClick={() => void save()}><Plus size={15} />Save voice</Button>} /><div className="grid items-start gap-5 xl:grid-cols-[1.1fr_0.9fr]"><Panel className="p-5 sm:p-6"><PanelTitle icon={MessageCircle} title="A new brand voice" detail="Build a profile to guide your drafts" /><div className="mt-5 space-y-4"><Field label="Brand name" htmlFor="brand-name"><Input id="brand-name" value={form.name} onChange={(event) => change("name", event.target.value)} placeholder="e.g. Sunday Supply" /></Field><Field label="What does your brand do?" htmlFor="brand-description"><Textarea id="brand-description" rows={3} value={form.description} onChange={(event) => change("description", event.target.value)} placeholder="A short, human description of your brand" /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Communication style" htmlFor="brand-style"><Input id="brand-style" value={form.style} onChange={(event) => change("style", event.target.value)} placeholder="e.g. Bright and grounded" /></Field><Field label="Preferred tone" htmlFor="brand-tone"><Select value={form.tone} onValueChange={(value) => change("tone", value)}><SelectTrigger id="brand-tone"><SelectValue /></SelectTrigger><SelectContent>{["Warm", "Playful", "Professional", "Bold", "Informative", "Minimal"].map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></Field></div><Field label="Who are you speaking to?" htmlFor="brand-audience"><Input id="brand-audience" value={form.audience} onChange={(event) => change("audience", event.target.value)} placeholder="e.g. Local coffee lovers" /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Words to use" htmlFor="brand-preferred"><Textarea id="brand-preferred" value={form.preferred_words} onChange={(event) => change("preferred_words", event.target.value)} rows={3} placeholder="Words or phrases you love" /></Field><Field label="Words to avoid" htmlFor="brand-avoided"><Textarea id="brand-avoided" value={form.avoided_words} onChange={(event) => change("avoided_words", event.target.value)} rows={3} placeholder="Words or phrases to leave out" /></Field></div><Button className="w-full" onClick={() => void save()}><Check size={15} />Save brand voice</Button></div></Panel><div className="space-y-4"><Panel className="p-5"><PanelTitle icon={Users} title="Your voices" detail={`${brands.length} ${brands.length === 1 ? "profile" : "profiles"} saved`} />{brands.length ? <div className="mt-4 space-y-2">{brands.map((voice) => <button key={voice.id} onClick={() => select(voice.id)} className={`w-full rounded-md border p-4 text-left transition ${selected === voice.id ? "border-primary/50 bg-secondary/50" : "border-border hover:bg-muted"}`}><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-md bg-accent text-accent-foreground"><MessageCircle size={15} /></span><span className="min-w-0 flex-1 truncate text-sm font-semibold">{voice.name}</span>{selected === voice.id && <Check size={15} className="text-primary" />}</div><p className="mt-2 line-clamp-2 text-xs leading-relaxed text-muted-foreground">{voice.description || voice.style}</p><span className="mt-3 inline-block rounded-full bg-muted px-2 py-1 text-[10px] text-muted-foreground">{voice.tone}</span></button>)}</div> : <EmptyState icon={MessageCircle} title="No voices yet" copy="Save a profile to make your AI drafts feel more like you." />}</Panel><Panel className="bg-muted/50 p-5"><PanelTitle icon={Sparkles} title="Why it helps" /><p className="mt-3 text-xs leading-relaxed text-muted-foreground">Your tone, audience, and vocabulary are included in your brief whenever you create a post. Choose a profile on the generator page to use it.</p></Panel></div></div></>;
}

function SettingsPage({ demo, name, setName }: { demo: boolean; name: string; setName: (v: string) => void }) {
  const [email, setEmail] = useState("");
  const [emailReady, setEmailReady] = useState(false);
  const [notifications, setNotifications] = useState({ schedule: true, weekly: false });
  useEffect(() => { if (!demo) void supabase.auth.getUser().then(({ data }) => { setEmail(data.user?.email ?? ""); setEmailReady(true); }); }, [demo]);
  const [savedName, setSavedName] = useState(name);
  const saveProfile = async () => {
    if (demo) { setSavedName(name); toast.success("Demo profile updated in this session"); return; }
    const { data } = await supabase.auth.getUser();
    if (!data.user) return;
    const { error } = await supabase.from("profiles").update({ display_name: name, updated_at: new Date().toISOString() }).eq("id", data.user.id);
    if (error) toast.error("Could not save your profile."); else { setSavedName(name); toast.success("Profile saved"); }
  };
  return <><PageHeading eyebrow="Your space, your settings" title="Account settings." copy="A few controls to keep your workspace comfortable." /><div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><div className="space-y-5"><Panel className="p-5 sm:p-6"><PanelTitle icon={Users} title="Profile" detail="Your name and account details" /><div className="mt-5 space-y-4"><Field label="Display name" htmlFor="settings-name"><Input id="settings-name" value={name} onChange={(event) => setName(event.target.value)} /></Field><Field label="Email address" htmlFor="settings-email"><Input id="settings-email" value={demo ? "demo@socialpilota.example" : emailReady ? email : "Loading…"} readOnly /></Field><Button onClick={() => void saveProfile()}>Save profile</Button></div></Panel><Panel className="p-5 sm:p-6"><PanelTitle icon={Activity} title="Notifications" detail="Choose what lands in your inbox" /><div className="mt-4 divide-y divide-border">{[{ key: "schedule" as const, title: "Upcoming schedule reminders", detail: "A heads-up before planned posts" }, { key: "weekly" as const, title: "Weekly summary", detail: "A quick recap of your content activity" }].map((item) => <label key={item.key} className="flex cursor-pointer items-center justify-between gap-4 py-4"><span><span className="block text-sm font-medium">{item.title}</span><span className="mt-1 block text-xs text-muted-foreground">{item.detail}</span></span><input type="checkbox" checked={notifications[item.key]} onChange={(event) => setNotifications({ ...notifications, [item.key]: event.target.checked })} aria-label={item.title} className="h-4 w-4 accent-primary" /></label>)}</div></Panel></div><div className="space-y-5"><Panel className="p-5"><PanelTitle icon={Target} title="Social accounts" detail="Connect when the official flow is ready" /><div className="mt-4 space-y-2">{PLATFORMS.map((item) => <div key={item} className="flex items-center gap-3 rounded-md border border-border p-3"><span className={`grid h-9 w-9 place-items-center rounded-md ${platformClass[item]}`}>{item === "Instagram" ? <Sparkles size={16} /> : item === "Facebook" ? <Users size={16} /> : <BarChart3 size={16} />}</span><div className="min-w-0 flex-1"><p className="text-xs font-medium">{item}</p><p className="text-[10px] text-muted-foreground">Not connected</p></div><Button variant="outline" size="sm" onClick={() => toast.info("Official account connection is not configured yet.")}>Connect</Button></div>)}</div><p className="mt-4 text-[10px] leading-relaxed text-muted-foreground">The connection buttons are placeholders. No account is connected until official platform OAuth and API access are configured.</p></Panel><Panel className="p-5"><PanelTitle icon={CircleHelp} title="Publishing & analytics" /><p className="mt-3 text-xs leading-relaxed text-muted-foreground">Posts can be organized and scheduled for internal planning. Live publishing and account analytics are not active yet.</p><div className="mt-4 rounded-md bg-muted p-3 text-[10px] text-muted-foreground">Account profile: {savedName || "Not set"}</div></Panel></div></div></>;
}
